<?php require_once __DIR__ . '/partials.php'; require_admin(); require_once __DIR__ . '/../config/database.php'; admin_header('Bookings'); $bookings = []; try { $bookings = db()->query('SELECT b.*, s.name AS service_name FROM bookings b LEFT JOIN services s ON s.id = b.service_id ORDER BY b.created_at DESC')->fetchAll(); } catch (Throwable $exception) {} ?>
<section class="panel"><table><thead><tr><th>Client</th><th>Service</th><th>Date/Time</th><th>Contact</th><th>Status</th></tr></thead><tbody><?php foreach ($bookings as $booking): ?><tr><td><strong><?= e($booking['client_name']) ?></strong><br><?= e($booking['company_name']) ?></td><td><?= e($booking['service_name'] ?? 'Service') ?></td><td><?= e($booking['preferred_date']) ?> <?= e($booking['preferred_time']) ?></td><td><?= e($booking['client_email']) ?><br><?= e($booking['client_phone']) ?></td><td><span class="badge"><?= e($booking['status']) ?></span></td></tr><?php endforeach; if (!$bookings): ?><tr><td colspan="5">No bookings found. Confirm database setup if this is unexpected.</td></tr><?php endif; ?></tbody></table></section>
<?php admin_footer(); ?>
